package com.tickanddone
import android.app.*
import android.appwidget.*
import android.content.*
import android.graphics.Color
import android.net.Uri
import android.os.*
import android.view.View
import android.widget.*
import org.json.JSONObject
import org.json.JSONArray

object Widgets {
 fun kind(c:Context,id:Int):String {val provider=AppWidgetManager.getInstance(c).getAppWidgetInfo(id)?.provider?.className?:"";return if(provider.endsWith("MoviesWidget"))"movie" else "todo"}
 fun prefs(c:Context,id:Int)=c.getSharedPreferences("widget-$id",Context.MODE_PRIVATE)
 fun refresh(c:Context){val manager=AppWidgetManager.getInstance(c);for(type in listOf(TodosWidget::class.java,MoviesWidget::class.java)){val ids=manager.getAppWidgetIds(ComponentName(c,type));for(id in ids)render(c,id);manager.notifyAppWidgetViewDataChanged(ids,R.id.widget_list)}}
 fun launch(c:Context,kind:String,id:String?=null)=Intent(c,MainActivity::class.java).setAction(Intent.ACTION_VIEW).setData(Uri.parse("tickanddone://list/$kind"+(id?.let{"?item=$it"}?:""))).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP)
 fun render(c:Context,id:Int){val kind=kind(c,id);val p=prefs(c,id);val manager=AppWidgetManager.getInstance(c);val signed=TickRepository.get(c).account()!=null;val remote=RemoteViews(c.packageName,R.layout.widget_list);val light=p.getBoolean("light",false);val text=if(light)Color.rgb(35,40,32) else Color.rgb(247,248,239)
  remote.setInt(R.id.widget_root,"setBackgroundResource",if(light)R.drawable.widget_light else when(p.getInt("opacity",1)){0->R.drawable.widget_low;2->R.drawable.widget_high;else->R.drawable.widget_background})
  remote.setTextViewText(R.id.widget_title,p.getString("title",if(kind=="todo")"Todos" else "Movies"));for(v in listOf(R.id.widget_title,R.id.widget_add,R.id.widget_settings,R.id.widget_empty,R.id.widget_undo))remote.setTextColor(v,text)
  remote.setTextViewText(R.id.widget_empty,if(signed)if(kind=="todo")"A little breathing room." else "Room for a good story." else "Open Tick and Done to sign in")
  remote.setOnClickPendingIntent(R.id.widget_title,PendingIntent.getActivity(c,id*10,launch(c,kind),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE))
  remote.setOnClickPendingIntent(R.id.widget_add,PendingIntent.getActivity(c,id*10+1,Intent(c,QuickAddActivity::class.java).putExtra("kind",kind).setData(Uri.parse("tickanddone://add/$id")),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE))
  remote.setOnClickPendingIntent(R.id.widget_settings,PendingIntent.getActivity(c,id*10+2,Intent(c,WidgetConfigActivity::class.java).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id).setData(Uri.parse("tickanddone://settings/$id")),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE))
  val service=Intent(c,WidgetRowsService::class.java).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);service.data=Uri.parse(service.toUri(Intent.URI_INTENT_SCHEME));remote.setRemoteAdapter(R.id.widget_list,service);remote.setEmptyView(R.id.widget_list,R.id.widget_empty)
  val template=Intent(c,WidgetActionReceiver::class.java).putExtra("kind",kind).setData(Uri.parse("tickanddone://action/$id"));remote.setPendingIntentTemplate(R.id.widget_list,PendingIntent.getBroadcast(c,id*10+3,template,PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_MUTABLE))
  val undo=TickRepository.get(c).read().optJSONObject("undo");val visible=signed&&undo!=null&&undo.optLong("until")>System.currentTimeMillis();remote.setViewVisibility(R.id.widget_undo,if(visible)View.VISIBLE else View.GONE)
  remote.setOnClickPendingIntent(R.id.widget_undo,PendingIntent.getBroadcast(c,id*10+4,Intent(c,WidgetActionReceiver::class.java).putExtra("action","undo").putExtra("kind",kind).setData(Uri.parse("tickanddone://undo/$id")),PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE))
  manager.updateAppWidget(id,remote)
  if(visible)Handler(Looper.getMainLooper()).postDelayed({render(c,id)},maxOf(1,(undo!!.optLong("until")-System.currentTimeMillis())))
 }
}
open class ListWidget:AppWidgetProvider(){override fun onUpdate(c:Context,m:AppWidgetManager,ids:IntArray){for(id in ids)Widgets.render(c,id)};override fun onAppWidgetOptionsChanged(c:Context,m:AppWidgetManager,id:Int,b:Bundle){Widgets.render(c,id)};override fun onDeleted(c:Context,ids:IntArray){for(id in ids)Widgets.prefs(c,id).edit().clear().apply()}}
class TodosWidget:ListWidget()
class MoviesWidget:ListWidget()
class WidgetRowsService:RemoteViewsService(){override fun onGetViewFactory(i:Intent):RemoteViewsFactory=Rows(this,i.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,0))}
class Rows(private val c:Context,private val widgetId:Int):RemoteViewsService.RemoteViewsFactory{
 private var rows=listOf<JSONObject>();override fun onCreate(){};override fun onDestroy(){};override fun onDataSetChanged(){val kind=Widgets.kind(c,widgetId);val items=TickRepository.get(c).read().getJSONArray("items");rows=(0 until items.length()).map{items.getJSONObject(it)}.filter{it.optString("kind")==kind&&!it.optBoolean("done")&&it.isNull("deletedAt")}.sortedBy{it.optDouble("position")}}
 override fun getCount()=rows.size;override fun getViewTypeCount()=1;override fun getItemId(position:Int)=rows[position].getString("id").hashCode().toLong();override fun hasStableIds()=true;override fun getLoadingView():RemoteViews?=null
 override fun getViewAt(position:Int):RemoteViews?{val item=rows.getOrNull(position)?:return null;return RemoteViews(c.packageName,R.layout.widget_row).apply{setTextViewText(R.id.row_title,item.getString("title"));val path=item.optString("poster");val file=TickRepository.get(c).posterFile(path);val show=Widgets.prefs(c,widgetId).getBoolean("posters",false)&&file.exists();setViewVisibility(R.id.row_poster,if(show)View.VISIBLE else View.GONE);if(show)setImageViewBitmap(R.id.row_poster,android.graphics.BitmapFactory.decodeFile(file.path));setTextColor(R.id.row_title,if(Widgets.prefs(c,widgetId).getBoolean("light",false))Color.rgb(35,40,32) else Color.WHITE);setOnClickFillInIntent(R.id.row_title,Intent().putExtra("action","open").putExtra("id",item.getString("id")));setOnClickFillInIntent(R.id.row_check,Intent().putExtra("action","complete").putExtra("id",item.getString("id")));setContentDescription(R.id.row_check,"Complete ${item.getString("title")}");setContentDescription(R.id.row_title,"Open ${item.getString("title")}")}}
}
class WidgetActionReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){val action=i.getStringExtra("action");val kind=i.getStringExtra("kind")?:"todo";if(action=="open"){c.startActivity(Widgets.launch(c,kind,i.getStringExtra("id")));return};val pending=goAsync();Thread{try{val m=JSONObject().put("kind",kind).put("action",if(action=="undo")"undo" else "patch").put("id",i.getStringExtra("id")).put("patch",JSONObject().put("done",true));TickRepository.get(c).mutate(m.toString())}finally{pending.finish()}}.start()}}
class QuickAddActivity:Activity(){override fun onCreate(b:Bundle?){super.onCreate(b);val kind=intent.getStringExtra("kind")?:"todo";if(TickRepository.get(this).account()==null){startActivity(Widgets.launch(this,kind));finish();return};val input=EditText(this).apply{hint=if(kind=="todo")"What’s on your mind?" else "Movie or TV title";setSingleLine(false);setPadding(28,18,28,18)};val dialog=AlertDialog.Builder(this).setTitle(if(kind=="todo")"Add a todo" else "Add to Movies").setView(input).setPositiveButton("Add",null).setNegativeButton("Cancel"){_,_->finish()}.setOnCancelListener{finish()}.create();dialog.setOnShowListener{input.requestFocus();dialog.window?.setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener{val title=input.text.toString().trim();if(title.isEmpty()){input.error="Enter a title";return@setOnClickListener};try{TickRepository.get(this).mutate(JSONObject().put("kind",kind).put("patch",JSONObject().put("title",title)).toString());finish()}catch(e:Exception){input.error=e.message}}};dialog.show()}}
class WidgetConfigActivity:Activity(){override fun onCreate(b:Bundle?){super.onCreate(b);val id=intent.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,AppWidgetManager.INVALID_APPWIDGET_ID);setResult(RESULT_CANCELED);if(id==AppWidgetManager.INVALID_APPWIDGET_ID){finish();return};val p=Widgets.prefs(this,id);val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(36,30,36,20)};val title=EditText(this).apply{hint="Widget title";setText(p.getString("title",if(Widgets.kind(this@WidgetConfigActivity,id)=="todo")"Todos" else "Movies"))};box.addView(title);val light=CheckBox(this).apply{text="Light appearance";isChecked=p.getBoolean("light",false)};box.addView(light);val posters=CheckBox(this).apply{text="Small poster thumbnails";isChecked=p.getBoolean("posters",false);visibility=if(Widgets.kind(this@WidgetConfigActivity,id)=="movie")View.VISIBLE else View.GONE};box.addView(posters);box.addView(TextView(this).apply{text="Background opacity";setPadding(0,24,0,5)});val opacity=SeekBar(this).apply{max=2;progress=p.getInt("opacity",1)};box.addView(opacity);AlertDialog.Builder(this).setTitle("Make it yours").setView(box).setPositiveButton("Save"){_,_->p.edit().putString("title",title.text.toString().ifBlank{"Todos"}).putBoolean("light",light.isChecked).putBoolean("posters",posters.isChecked).putInt("opacity",opacity.progress).apply();Widgets.render(this,id);setResult(RESULT_OK,Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id));finish()}.setNegativeButton("Cancel"){_,_->finish()}.setOnCancelListener{finish()}.show()}}
